// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(block.timestamp + 1); // balance becomes 1 ether (reference) or 0.5 ether (bug)
        vm.warp(block.timestamp + 2);
        vm.prank(user);
        c.Collect(0.5 ether); // tries to collect 0.5 ether
        // Collect succeeds only if balance >= 0.5 ether. In reference: balance = 1 - 0.5 = 0.5; in bug: balance = 0.5 - 0.5 = 0
        // After Collect, check the stored balance via public getter
        ( , uint256 balAfter) = c.Acc(user);
        assertTrue(balAfter == 0.5 ether, "balance should be 0.5 ether in correct contract; bug differs");
    }
}

